<?php require __DIR__.'/app/bootstrap.php';admin_required();$tab=$_GET['tab']??'songs';$tabs=['songs','importer','artists','categories','ads','settings'];if(!in_array($tab,$tabs,true))$tab='songs';$notice='';$importJobId='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$act=$_POST['action']??'';try{
if($act==='song'){ $title=trim($_POST['title']??'');if(!$title)throw new RuntimeException('Song title is required');$media=trim($_POST['media_url']??'');$rights=trim($_POST['rights_note']??'');if($media&&!filter_var($media,FILTER_VALIDATE_URL))throw new RuntimeException('Media URL is invalid');if($media&&!$rights)throw new RuntimeException('Add a rights/permission note for media links');$slug=slugify(trim($_POST['slug']??'')?:$title);$q=db()->prepare('INSERT INTO songs(title,slug,artist_id,category_id,album,release_date,description,artwork_url,media_url,media_type,rights_note,meta_title,meta_description,published) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$title,$slug,(int)($_POST['artist_id']??0)?:null,(int)($_POST['category_id']??0)?:null,trim($_POST['album']??''),trim($_POST['release_date']??''),trim($_POST['description']??''),trim($_POST['artwork_url']??''),$media,($_POST['media_type']??'stream')==='download'?'download':'stream',$rights,trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),isset($_POST['published'])?1:0]);$notice='Song saved';}
elseif($act==='delete_song'){db()->prepare('DELETE FROM songs WHERE id=?')->execute([(int)$_POST['id']]);$notice='Song deleted';}
elseif($act==='artist'){ $n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('Artist name required');db()->prepare('INSERT INTO artists(name,slug,bio) VALUES(?,?,?) ON CONFLICT(slug) DO UPDATE SET name=excluded.name,bio=excluded.bio')->execute([$n,slugify($n),trim($_POST['bio']??'')]);$notice='Artist saved';}
elseif($act==='category'){ $n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('Category name required');db()->prepare('INSERT INTO categories(name,slug) VALUES(?,?) ON CONFLICT(slug) DO NOTHING')->execute([$n,slugify($n)]);$notice='Category saved';}
elseif($act==='ad'){db()->prepare('INSERT INTO ads(name,placement,code,enabled) VALUES(?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['placement']),$_POST['code'],isset($_POST['enabled'])?1:0]);$notice='Ad saved';}
elseif($act==='import_pages'){
 $raw=trim($_POST['page_urls']??'');$urls=array_values(array_filter(array_map('trim',preg_split('/\\r?\\n/',$raw))));
 if(!$urls||count($urls)>20)throw new RuntimeException('Enter between 1 and 20 category page URLs, one per line.');
 foreach($urls as $u){$p=parse_url($u);if(($p['scheme']??'')!=='https'||!in_array(strtolower($p['host']??''),['djjohal.com','www.djjohal.com'],true)||!preg_match('~^/category/single-track(?:/\\d+)?\\.html$~i',$p['path']??''))throw new RuntimeException('Only approved Single Track category page URLs are accepted: '.$u);}
 $job=importer_post('/admin/import-pages',['urls'=>$urls]);
 $importJobId=(string)($job['job_id']??'');
 if($importJobId==='') throw new RuntimeException('Importer did not return a job ID.');
 $notice='Import queued. Keep this page open while JattBeat processes the category pages.';
}
elseif($act==='settings'){save_setting('site_name',trim($_POST['site_name']));save_setting('site_description',trim($_POST['site_description']));$notice='Settings saved';}
}catch(Throwable $ex){$notice='Error: '.$ex->getMessage();} }
$songs=db()->query('SELECT s.*,a.name artist FROM songs s LEFT JOIN artists a ON a.id=s.artist_id ORDER BY s.id DESC')->fetchAll();$artists=db()->query('SELECT * FROM artists ORDER BY name')->fetchAll();$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$ads=db()->query('SELECT * FROM ads ORDER BY id DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JattBeat Admin</title><link rel="stylesheet" href="/assets/style.css"></head><body><header class="top"><a class="brand" href="/">JattBeat Admin</a><nav><a href="/">Public site</a><a href="/sitemap.xml">Sitemap</a><a href="/logout.php">Logout <?=e($_SESSION['admin_name']??'')?></a></nav></header><main class="wrap"><h1>Music dashboard</h1><?php if($notice):?><p class="notice"><?=e($notice)?></p><?php endif?><nav class="tabs"><?php foreach(['songs'=>'Songs','importer'=>'Bulk Importer','artists'=>'Artists','categories'=>'Categories','ads'=>'Ads','settings'=>'Settings'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=$v?></a><?php endforeach?></nav>
<?php if($tab==='importer'):?><section class="panel"><h2>Bulk song importer</h2><p>Use your existing JattBeat Python importer. Paste one or more approved Single Track category URLs, one per line. Imported song metadata is saved directly into this PHP site's catalogue. Songs appear on the homepage after successful sync.</p><form id="bulk-import-form" method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="import_pages"><label class="wide">Category page URLs<textarea name="page_urls" rows="7" required placeholder="https://www.djjohal.com/category/single-track.html&#10;https://www.djjohal.com/category/single-track/2.html&#10;https://www.djjohal.com/category/single-track/3.html"></textarea></label><div class="wide"><button>Import all pages</button></div></form><div id="import-progress" class="notice" role="status" aria-live="polite" style="display:none;margin-top:16px"></div><p class="muted">Maximum 20 listing pages per batch. Existing songs are deduplicated. Import only catalogue metadata and media links you are authorized to use; a public listing does not grant redistribution rights.</p></section><?php elseif($tab==='songs'):?><section class="panel"><h2>Add song</h2><form method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="song"><label>Title<input name="title" required></label><label>Artist<select name="artist_id"><option value="">Choose artist</option><?php foreach($artists as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach?></select></label><label>Category<select name="category_id"><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label>Album<input name="album"></label><label>Release date<input type="date" name="release_date"></label><label>Artwork URL<input type="url" name="artwork_url"></label><label>Authorized stream/download URL<input type="url" name="media_url"></label><label>Link type<select name="media_type"><option value="stream">Stream</option><option value="download">Download</option></select></label><label>Rights/permission note<input name="rights_note" placeholder="License, ownership or permission reference"></label><label>SEO title<input name="meta_title"></label><label>SEO description<input name="meta_description"></label><label class="wide">Description<textarea name="description" rows="3"></textarea></label><label class="check"><input type="checkbox" name="published"> Publish</label><div><button>Save song</button></div></form></section><h2>Catalogue</h2><input id="search" placeholder="Search songs..." oninput="document.querySelectorAll('#rows tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(this.value.toLowerCase()))"><div class="tablewrap"><table><thead><tr><th>Song</th><th>Artist</th><th>Status</th><th>Actions</th></tr></thead><tbody id="rows"><?php foreach($songs as $s):?><tr><td><?=e($s['title'])?></td><td><?=e($s['artist']??'—')?></td><td><?=$s['published']?'Published':'Draft'?></td><td><a href="/song/<?=e($s['slug'])?>">View</a> <form class="inline" method="post" onsubmit="return confirm('Delete song?')"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_song"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="danger small">Delete</button></form></td></tr><?php endforeach?></tbody></table></div>
<?php elseif($tab==='artists'):?><section class="panel"><h2>Add artist</h2><form method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="artist"><label>Name<input name="name" required></label><label>Bio<input name="bio"></label><button>Save artist</button></form></section><ul><?php foreach($artists as $a):?><li><?=e($a['name'])?></li><?php endforeach?></ul>
<?php elseif($tab==='categories'):?><section class="panel"><h2>Add category</h2><form method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="category"><label>Name<input name="name" required></label><button>Save category</button></form></section><ul><?php foreach($cats as $c):?><li><?=e($c['name'])?></li><?php endforeach?></ul>
<?php elseif($tab==='ads'):?><section class="panel"><h2>Ad placements</h2><p>Only trusted admins should insert third-party HTML/JavaScript ad snippets.</p><form method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="ad"><label>Name<input name="name" required></label><label>Placement<select name="placement"><option value="home">Homepage</option><option value="song">Song page</option></select></label><label class="wide">Ad code<textarea name="code" rows="4" required></textarea></label><label class="check"><input type="checkbox" name="enabled" checked> Enabled</label><button>Save ad</button></form></section><ul><?php foreach($ads as $a):?><li><?=e($a['name'])?> — <?=e($a['placement'])?></li><?php endforeach?></ul>
<?php else:?><section class="panel"><h2>Site settings</h2><form method="post" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="settings"><label>Site name<input name="site_name" value="<?=e(setting('site_name','JattBeat'))?>"></label><label>Site description<input name="site_description" value="<?=e(setting('site_description'))?>"></label><button>Save settings</button></form></section><?php endif?></main>
<?php if($tab==='importer' && $importJobId!==''): ?>
<script>
(()=>{const box=document.getElementById('import-progress');if(!box)return;const jobId=<?=json_encode($importJobId)?>;box.style.display='block';let tries=0;async function poll(){try{const r=await fetch('/import-status.php?id='+encodeURIComponent(jobId),{cache:'no-store',credentials:'same-origin'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Status request failed');box.textContent=(d.progress||d.status||'Import running')+' | New: '+(d.result?.created??0)+' | Duplicates: '+(d.result?.duplicates_skipped??0)+' | Errors: '+(d.result?.errors?.length??0);if(d.status==='completed'){box.textContent='Import completed. Pages: '+(d.result?.pages_checked??0)+' | Song pages found: '+(d.result?.song_pages_found??0)+' | New records: '+(d.result?.created??0)+' | Duplicates: '+(d.result?.duplicates_skipped??0)+' | PHP catalogue synced: '+(d.result?.php_catalogue_synced??0)+' | Errors: '+(d.result?.errors?.length??0);return;}if(d.status==='failed'){box.textContent='Import failed: '+(d.error||d.progress||'Unknown error');return;}if(++tries<120){setTimeout(poll,2500);}else{box.textContent+=' | Still running. Refresh this page shortly to check again.';}}catch(e){box.textContent='Could not check import status: '+e.message;}}poll();})();
</script>
<?php endif ?>
</body></html>